def solve():
    n, a, b, c = map(int, input().split())

    # dp[i] = maximum number of pieces for ribbon length i
    dp = [-1] * (n + 1)
    dp[0] = 0  # 0 length ribbon has 0 pieces

    for i in range(1, n + 1):
        # Try all three possible cuts
        if i >= a and dp[i - a] != -1:
            dp[i] = max(dp[i], dp[i - a] + 1)
        if i >= b and dp[i - b] != -1:
            dp[i] = max(dp[i], dp[i - b] + 1)
        if i >= c and dp[i - c] != -1:
            dp[i] = max(dp[i], dp[i - c] + 1)

    print(dp[n])

solve()
