def count_trailing_zeros(n, b):
    """Count trailing zeros in base b representation of n!"""

    # Factorize b
    factors = {}
    temp = b

    # Check for small prime factors
    for i in range(2, int(temp**0.5) + 1):
        while temp % i == 0:
            factors[i] = factors.get(i, 0) + 1
            temp //= i

    # If remaining temp is > 1, it's a prime factor
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # If no prime factors found (b=1?), return 0
    if not factors:
        return 0

    # For each prime factor, find highest power that divides n!
    max_powers = {}
    for p, exp in factors.items():
        power = 0
        current = p
        while current <= n:
            power += n // current
            current *= p
        max_powers[p] = power

    # Calculate trailing zeros
    trailing_zeros = float('inf')
    for p, power in max_powers.items():
        trailing_zeros = min(trailing_zeros, power // factors[p])

    return trailing_zeros

def main():
    data = input().split()
    n = int(data[0])
    b = int(data[1])

    result = count_trailing_zeros(n, b)
    print(result)

if __name__ == "__main__":
    main()
"}

