import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    li = list(map(int, data[1:n+1]))
    ci = list(map(int, data[n+1:2*n+1]))

    # dp[gcd] = min cost to achieve this GCD
    # We use a dictionary for efficiency
    dp = {0: 0}

    for i in range(n):
        length = li[i]
        cost = ci[i]

        # Create a new temporary dictionary to avoid overwriting
        new_dp = {}

        # Propagate existing states
        for g in dp:
            new_g = gcd(g, length)
            new_cost = dp[g] + cost

            # Update new_dp
            if new_g not in new_dp or new_cost < new_dp[new_g]:
                new_dp[new_g] = new_cost

            # Also keep the original state
            if g not in new_dp or dp[g] < new_dp[g]:
                new_dp[g] = dp[g]

        # Merge new states into dp
        for g in new_dp:
            if g not in dp or new_dp[g] < dp[g]:
                dp[g] = new_dp[g]

    # Check if we can reach any cell (GCD = 1)
    if 1 in dp:
        print(dp[1])
    else:
        print(-1)

# Helper function for GCD
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

if __name__ == "__main__":
    solve()
"}

