def solve():
    n = int(sys.stdin.readline())

    # Create a matrix filled with even numbers
    matrix = [[2 * i + 2 * j for j in range(n)] for i in range(n)]

    # Place odd numbers in a cross shape through the center
    center = n // 2
    for i in range(n):
        for j in range(n):
            # Check if (i, j) is in the cross shape
            if i == center or j == center:
                matrix[i][j] += 1

    # Print the matrix
    for row in matrix:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
