def can_make_palindromes(strings, indices):
    """Check if we can make the strings at indices palindromic."""
    total_0 = 0
    total_1 = 0

    # Count total characters
    for i in indices:
        s = strings[i]
        total_0 += s.count('0')
        total_1 += s.count('1')

    # Check if all strings have even length
    all_even = True
    for i in indices:
        if len(strings[i]) % 2 == 1:
            all_even = False
            break

    if all_even:
        # All even-length strings: need even number of both 0s and 1s
        return total_0 % 2 == 0 and total_1 % 2 == 0
    else:
        # At least one odd-length string: just need at least one 0 or 1
        return total_0 > 0 or total_1 > 0


