    Q = int(input())

    for _ in range(Q):
        n = int(input())
        strings = []
        for _ in range(n):
            strings.append(input().strip())

        # Try all combinations of which strings to make palindromic
        max_palindromes = 0

        # Try making k palindromic strings, where k ranges from 0 to n
        for k in range(n, -1, -1):
            # Try all combinations of k strings
