import sys
from collections import defaultdict

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    m = int(next(it))
    n = int(next(it))

    # Map from monster ID to list of splits
    splits = defaultdict(list)

    for _ in range(m):
        mi = int(next(it))
        li = int(next(it))
        split = []

        for _ in range(li):
            val = int(next(it))
            split.append(val)

        splits[mi].append(split)

    # Memoization cache: frozenset(monster_ids) -> (min_diamonds, max_diamonds, has_infinite)
    memo = {}

    def dfs(monsters):
        # Base case: no monsters left
        if not monsters:
            return (0, 0, False)

        # Check memo
        key = frozenset(monsters)
        if key in memo:
            return memo[key]

        min_d = float('inf')
        max_d = -float('inf')
        has_inf = False

        # Try each monster in the current set
        for monster in monsters:
            # Try each split for this monster
            for split in splits[monster]:
                # Count diamonds and get new monsters
                diamonds = 0
                new_monsters = []

                for val in split:
                    if val == -1:
                        diamonds += 1
                    else:
                        new_monsters.append(val)

                # Recursively solve for new state
                if new_monsters:
                    # If there are new monsters, we need to solve for them
                    result = dfs(new_monsters)

                # Update results
                min_d = min(min_d, diamonds + result[0])
                max_d = max(max_d, diamonds + result[1])

                if result[2]:
                    has_inf = True

        # If no splits available, we can't eliminate all monsters
        if min_d == float('inf'):
            result = (-1, -1, False)
        else:
            result = (min_d, max_d, has_inf)

        memo[key] = result

        # Limit recursion depth by reducing maximum recursion depth
        sys.setrecursionlimit(max(1000, sys.getrecursionlimit() - 100))

        return result

    # Solve for each monster
    for monster_id in range(1, n + 1):
