    door_directions = []
    for i in range(n):
        row = []
        for j in range(m):
            char = grid[i][j]
            row.append(get_door_directions(char))
        door_directions.append(row)

    # Directions: 0=up, 1=right, 2=down, 3=left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    # BFS
    from collections import deque

    # State: (row, col, orientation, time)
    visited = [[[False] * 4 for _ in range(m)] for _ in range(n)]
    queue = deque()

    # Start at (xT-1, yT-1) with orientation 0
    queue.append((start[0], start[1], 0, 0))  # (row, col, orientation, time)
    visited[start[0]][start[1]][0] = True

    found = False
    answer = -1

    while queue:
