    n = int(data[0])
    k = int(data[1])
    m = int(data[2])
    a = int(data[3])

    votes = [0] * (n + 1)  # 1-indexed
    last_vote_time = [0] * (n + 1)

    for i in range(4, 4 + a):
        g = int(data[i])
        votes[g] += 1
        last_vote_time[g] = i - 3  # Time is 1-indexed by position in input

