    # Fill dp table
    for i in range(2, k + 1):
        for j in range(1, n + 1):
            # Sum of all sequences of length i-1 ending with a divisor of j
            dp[i][j] = sum(dp[i-1][d] for d in divisors[j]) % MOD

    # Answer is sum of all sequences of length k
    print(sum(dp[k][j] for j in range(1, n + 1)) % MOD)

