def count_strings(n, s):
    """Count binary strings of length n that contain s as a substring cyclically."""
    m = len(s)

    # State: number of characters of s matched so far
    # We want to count strings that eventually reach state m

    # DP[i][state] = number of strings of length i that end in state
    DP = [[0] * (m + 1) for _ in range(n + 1)]
    DP[0][0] = 1

    for i in range(n):
        for state in range(m + 1):
            if DP[i][state] == 0:
                continue

            for bit in [0, 1]:
                new_state = state
                if state < m:
                    if (bit == 0 and s[state] == '0') or (bit == 1 and s[state] == '1'):
                        new_state += 1

                DP[i + 1][new_state] += DP[i][state]

    # Count strings that end in state m
    return DP[n][m]

def solve():
