import sys

def contains_substring(s, target):
    """Check if target is a substring of s"""
    return target in s

def solve():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    count = 0

    # Generate all binary strings of length n
    for mask in range(1 << n):
        # Convert mask to binary string
        bits = []
        for i in range(n):
            bits.append('0' if (mask & (1 << i)) == 0 else '1')
        t = ''.join(bits)

        # Check if any rotation of t contains s as a substring
        contains = False
        for i in range(n):
            # Rotate t by i positions
            rotated = t[i:] + t[:i]
            if contains_substring(rotated, s):
                contains = True
                break

        if contains:
            count += 1

    print(count)

if __name__ == "__main__":
    solve()
