n = int(input())

# Build the tree
children = [[] for _ in range(n + 1)]
for _ in range(n - 1):
    u, v = map(int, input().split())
    children[u].append(v)

# Find leaves (nodes with no children)
leaves = []
for i in range(1, n + 1):
    if not children[i]:
        leaves.append(i)

# Compute depth of each leaf using BFS
from collections import deque
queue = deque([(1, 0)])  # (node, depth)
leaf_depths = {}

while queue:
    node, depth = queue.popleft()
    if not children[node]:
        leaf_depths[node] = depth
    for child in children[node]:
        queue.append((child, depth + 1))

# Sort leaves by depth and then by node number to break ties
leaves_sorted = sorted(leaves, key=lambda x: (leaf_depths[x], x))

# Shambambukli (maximizer)
# Put largest numbers on even depth leaves, smallest on odd depth leaves
max_result = 0
for i, leaf in enumerate(leaves_sorted):
    if leaf_depths[leaf] % 2 == 0:
        max_result = max(max_result, i + 1)
    else:
        max_result = min(max_result, i + 1)

# Mazukta (minimizer)
# Put smallest numbers on even depth leaves, largest on odd depth leaves
min_result = float('inf')
