import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    q = list(map(int, data[1:1+n-1]))

    # Compute prefix sums of q
    prefix_sums = [0] * (n - 1)
    for i in range(n - 1):
        if i == 0:
            prefix_sums[i] = q[i]
        else:
            prefix_sums[i] = prefix_sums[i - 1] + q[i]

    # Try all possible starting values
    for p1 in range(1, n + 1):
        seen = set()
        p = []
        p1_val = p1
        p.append(p1_val)
        for i in range(n - 1):
            p1_val += q[i]
            if p1_val < 1 or p1_val > n or p1_val in seen:
                break
            p.append(p1_val)
            seen.add(p1_val)

        if len(p) == n:
            print(' '.join(map(str, p)))
            return

    print(-1)

if __name__ == "__main__":
    solve()

