def get_doors(block, rotation):
    """Return set of directions this block has doors in given rotation"""
    if block == '+':
        return {0, 1, 2, 3}  # all directions
    elif block == '-':
        # left/right -> up/down
        return {rotation % 2, (rotation + 1) % 2}
    elif block == '|':
        # up/down -> left/right
        return {(rotation + 2) % 4, (rotation + 3) % 4}
    elif block == '^':
        # up -> right
        return {(rotation + 1) % 4}
    elif block == '>':
        # right -> down
        return {(rotation + 2) % 4}
    elif block == '<':
        # left -> up
        return {(rotation + 3) % 4}
    elif block == 'v':
        # down -> left
        return {(rotation + 0) % 4}
    elif block == 'L':
        # all except left -> all except up
        return {(rotation + 2) % 4, (rotation + 3) % 4, (rotation + 0) % 4}
    elif block == 'R':
        # all except right -> all except down
        return {(rotation + 0) % 4, (rotation + 1) % 4, (rotation + 3) % 4}
    elif block == 'U':
        # all except up -> all except right
        return {(rotation + 0) % 4, (rotation + 2) % 4, (rotation + 3) % 4}
    elif block == 'D':
        # all except down -> all except left
        return {(rotation + 1) % 4, (rotation + 2) % 4, (rotation + 3) % 4}
    elif block == '*':
        return set()
    else:
        return set()

def solve():
    n, m = map(int, input().split())
    grid = [input().strip() for _ in range(n)]

    xT, yT = map(int, input().split())
    xM, yM = map(int, input().split())

    # Convert to 0-indexed
    start = (xT - 1, yT - 1)
    end = (xM - 1, yM - 1)

    # BFS
    from collections import deque

    # State: (x, y, rotation)
    visited = [[[False] * 4 for _ in range(m)] for _ in range(n)]
    queue = deque([(start[0], start[1], 0, 0)])  # (x, y, rotation, time)
    visited[start[0]][start[1]][0] = True

    # Directions: 0=up, 1=right, 2=down, 3=left
    dirs = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    while queue:
        x, y, rot, time = queue.popleft()

        # Check if we reached the end
        if (x, y) == end:
            print(time)
            return

        # Try rotating
        new_rot = (rot + 1) % 4
        if not visited[x][y][new_rot]:
            visited[x][y][new_rot] = True
            queue.append((x, y, new_rot, time + 1))

        # Try moving
        for d in range(4):
            nx, ny = x + dirs[d][0], y + dirs[d][1]

