    n, k = map(int, input().split())

    # For the i-th set, use numbers: {4i-3, 4i-2, 4i-1, 4i+1} scaled by k
    # But we need to skip numbers that would cause overlap

    # Just use the first 4n numbers, partitioned into sets of 4
    # with the pattern: {4i-3, 4i-2, 4i-1, 4i+1}

    result = []
    used = set()

    for i in range(1, n + 1):
        # Find 4 distinct numbers that are pairwise coprime
        # Start from the first unused number
        start = 4 * i - 3
        while True:
            # Try the pattern
            nums = [start, start + 1, start + 2, start + 4]
            if all(num not in used for num in nums) and is_pairwise_coprime(nums):
                result.append([num * k for num in nums])
                used.update(nums)
                break
            start += 1

    print(5 * k + (n - 1) * 4 * k)
    for s in result:
