    outcomes = [0] * (n + 1)

    # For candidate i to be guaranteed:
    # They must be in the top k for all distributions
    # votes[i] > votes[j] for at least k-1 candidates
    for i in range(1, n + 1):
        # Count how many candidates have fewer votes than i
        count = 0
        for j in range(1, n + 1):
            if i != j and votes[i] > votes[j]:
                count += 1
        if count >= k - 1:
            outcomes[i] = 1
        else:
            # Check if they can have a chance
            # votes[i] + rem > votes[j] for at least k-1 candidates
            count = 0
            for j in range(1, n + 1):
                if i != j and votes[i] + rem > votes[j]:
                    count += 1
            if count >= k - 1:
