def solve():
    n = int(input())
    trees = []
    for _ in range(n):
        x, h = map(int, input().split())
        trees.append((x, h))

    # dp[i][0]: max trees fell with i-th tree left standing
    # dp[i][1]: max trees fell with i-th tree fell to left
    # dp[i][2]: max trees fell with i-th tree fell to right

    dp = [[0, 0, 0] for _ in range(n)]

    # Base case: first tree
    # Can fell to left: [x0-h0, x0] doesn't block anyone
    if trees[0][1] <= trees[0][0]:
        dp[0][1] = 1
    # Can fell to right: [x0, x0+h0] doesn't block anyone
    if trees[0][0] <= trees[0][1]:
        dp[0][2] = 1
    # Can leave standing
    dp[0][0] = 0

    for i in range(1, n):
        x_i, h_i = trees[i]
        x_prev, h_prev = trees[i-1]

        # Case 1: i-th tree left standing
        dp[i][0] = max(dp[i-1][0], dp[i-1][1], dp[i-1][2])

        # Case 2: i-th tree fell to left
        # Check if previous state allows this
        if dp[i-1][0] > 0:
            # Previous tree left standing
            # Current fell to left occupies [x_i-h_i, x_i]
            # Check if this segment overlaps with previous point x_prev
            if x_prev >= x_i - h_i:
                # Overlap, can't fell to left
                dp[i][1] = 0
            else:
                dp[i][1] = dp[i-1][0] + 1
        elif dp[i-1][1] > 0:
            # Previous tree fell to left
            # Current fell to left occupies [x_i-h_i, x_i]
            # Previous segment: [x_prev-h_prev, x_prev]
            if x_i - h_i <= x_prev - h_prev:
                # Overlap at leftmost point
                dp[i][1] = 0
            else:
                dp[i][1] = dp[i-1][1] + 1
        elif dp[i-1][2] > 0:
            # Previous tree fell to right
            # Current fell to left occupies [x_i-h_i, x_i]
            # Previous segment: [x_prev, x_prev+h_prev]
            if x_i - h_i <= x_prev + h_prev:
                # Overlap at rightmost point
                dp[i][1] = 0
            else:
                dp[i][1] = dp[i-1][2] + 1
        else:
            dp[i][1] = 0

        # Case 3: i-th tree fell to right
        if dp[i-1][0] > 0:
            # Previous tree left standing
            # Current fell to right occupies [x_i, x_i+h_i]
            if x_prev >= x_i:
                # Overlap
                dp[i][2] = 0
            else:
                dp[i][2] = dp[i-1][0] + 1
        elif dp[i-1][1] > 0:
            # Previous tree fell to left
            # Current fell to right occupies [x_i, x_i+h_i]
            if x_i - h_i <= x_prev:
                # Overlap
                dp[i][2] = 0
            else:
                dp[i][2] = dp[i-1][1] + 1
        elif dp[i-1][2] > 0:
            # Previous tree fell to right
