def is_good(s):
    """Check if a string is good (no "010" or "101" as subsequences)"""
    # Check for "010" subsequence
    has_0 = False
    has_1 = False
    for c in s:
        if c == '0':
            has_0 = True
        elif c == '1':
            if has_0:
                has_1 = True
        if has_0 and has_1:
            return False

    # Check for "101" subsequence
    has_1 = False
    has_0 = False
    for c in s:
        if c == '1':
            has_1 = True
        elif c == '0':
            if has_1:
                has_0 = True
        if has_1 and has_0:
            return False

