def count_good_sequences(n, k):
    MOD = 1000000007

    # dp[i][j] = number of good sequences of length j ending with i
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base case: sequences of length 1
    for i in range(1, n + 1):
        dp[i][1] = 1

    # Fill the DP table
    for length in range(2, k + 1):
        for end in range(1, n + 1):
            # Sum over all divisors of end
            total = 0
            for d in range(1, end + 1):
                if end % d == 0:
                    total = (total + dp[d][length - 1]) % MOD
            dp[end][length] = total

    # Sum all sequences of length k
    result = sum(dp[i][k] for i in range(1, n + 1)) % MOD
    return result

