import sys

def is_unlucky(ticket: str, n: int) -> bool:
    """Check if the ticket meets the unluckiness criterion."""
    first_half = ticket[:n]
    second_half = ticket[n:]

    # Check if all digits in first half are strictly less than corresponding digits in second half
    first_less = True
    for i in range(n):
        if int(first_half[i]) >= int(second_half[i]):
            first_less = False
            break

    # Check if all digits in first half are strictly greater than corresponding digits in second half
    first_greater = True
    for i in range(n):
        if int(first_half[i]) <= int(second_half[i]):
            first_greater = False
            break

    return first_less or first_greater

def main():
    n = int(sys.stdin.readline())
    ticket = sys.stdin.readline().strip()

    if is_unlucky(ticket, n):
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()
"}

