def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    a = [int(next(it)) for _ in range(n)]

    # Map each value to a list of its positions (1-indexed)
    pos_map = {}
    for idx, val in enumerate(a, start=1):
        if val not in pos_map:
            pos_map[val] = []
        pos_map[val].append(idx)

    # For each value, precompute the minimum distances between consecutive positions
    min_dist_map = {}
    for val, positions in pos_map.items():
        if len(positions) < 2:
            continue

        min_dist = float('inf')
        for i in range(len(positions) - 1):
            dist = abs(positions[i] - positions[i + 1])
            if dist < min_dist:
                min_dist = dist

        min_dist_map[val] = min_dist

    # Process each query
    out_lines = []
    for _ in range(m):
        lj = int(next(it))
        rj = int(next(it))

        min_dist = float('inf')

        # Check each value
        for val, positions in pos_map.items():
            # Use binary search to find positions in [lj, rj]
            left = bisect.bisect_left(positions, lj)
            right_idx = bisect.bisect_right(positions, rj)

            if right_idx - left >= 2:
                # There are at least two positions in the range
                # Check adjacent positions in this range
                for i in range(left, right_idx - 1):
                    dist = abs(positions[i] - positions[i + 1])
                    if dist < min_dist:
                        min_dist = dist

        if min_dist == float('inf'):
            out_lines.append('-1')
        else:
            out_lines.append(str(min_dist))

    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
