import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    q = list(map(int, data[1:1+n-1]))

    # Compute prefix sums of q
    prefix_sums = [0] * n
    for i in range(1, n):
        prefix_sums[i] = prefix_sums[i-1] + q[i-1]

    # Try all possible starting values p_1
    for p1 in range(1, n + 1):
        valid = True
        seen = set()
        for i in range(n):
            pi = p1 + prefix_sums[i]
            if pi < 1 or pi > n or pi in seen:
                valid = False
                break
            seen.add(pi)

        if valid:
            print(' '.join(map(str, [p1 + prefix_sums[i] for i in range(n)])))
            return

    print(-1)

if __name__ == "__main__":
    solve()
